import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"震下离上 噬嗑：","description":"京氏易传 - 震下离上 噬嗑：","frontmatter":{"title":"震下离上 噬嗑：","description":"京氏易传 - 震下离上 噬嗑："},"headers":[],"relativePath":"zh/classics/jingshi/047.md","filePath":"zh/classics/jingshi/047.md"}'),r={name:"zh/classics/jingshi/047.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"震下离上-噬嗑",tabindex:"-1"},[i("震下离上 噬嗑： "),e("a",{class:"header-anchor",href:"#震下离上-噬嗑","aria-label":"Permalink to “震下离上 噬嗑：”"},"​")],-1),e("p",null,"柔来文刚，积气居中，阴道明白，动见文明。雷电合，分威光，而噬嗑也。《易》曰：“颐中有物，曰噬嗑”。阴阳分中，动而明；【象雷电也。】物有不齐，齧而噬。（虎易注：齧为（啮）的繁体字，读音：nie，四声。意为：啃或咬。）吉凶之道，象于五行。顺则吉，逆则凶。火木合卦配升降。与离为飞伏。【己未土，辛巳火。】六五居尊，应六二大夫。",-1),e("p",null,"建始丙午至辛亥，【芒种，小雪。】积算起辛亥至庚戌，周而复始。火土入离震。【分火土二位入噬嗑卦，起积算爻，推配星辰，岁月日时，进退吉凶。】",-1),e("p",null,"五星从位起镇星，【土星入卦。】女宿从位降己未土，【二十八宿，分女宿入卦六五己未土也。】分气候二十八。【从二十八位数起八卦，算吉凶。】",-1),e("p",null,"火居水上，阳中见阴，阳杂气浑而溷，（虎易注：溷：读音：hun，四声。意为：混浊。）吉凶适变，随时见也。返复阴，游魂入卦。【降下九四阳入阴。】五行进退，始终之道，斯可验矣。升降六爻，极返终，下降山雷颐卦。",-1)])])}const _=s(r,[["render",l]]);export{u as __pageData,_ as default};
